// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract ApplicationPayment {

    address public owner;

    struct PaymentInfo {
        address payer;
        string kantahCode;
        uint256 area;
        uint256 amount;
        uint256 timestamp;
    }

    struct KantahFee {
        uint256 landPricePerM2;
        uint256 registrationFee;
        bool exists;
    }

    // applicationId => payment
    mapping(string => PaymentInfo) public payments;

    // kantahCode => fee config
    mapping(string => KantahFee) public kantahFees;

    event KantahFeeUpdated(
        string kantahCode,
        uint256 landPricePerM2,
        uint256 registrationFee
    );

    event PaymentReceived(
        string indexed applicationId,
        string kantahCode,
        address indexed payer,
        uint256 area,
        uint256 amount,
        uint256 timestamp
    );

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function setKantahFee(
        string memory kantahCode,
        uint256 landPricePerM2,
        uint256 registrationFee
    )
        external
        onlyOwner
    {
        require(landPricePerM2 > 0, "Invalid land price");

        kantahFees[kantahCode] = KantahFee({
            landPricePerM2: landPricePerM2,
            registrationFee: registrationFee,
            exists: true
        });

        emit KantahFeeUpdated(
            kantahCode,
            landPricePerM2,
            registrationFee
        );
    }

    function calculateCost(
        string memory kantahCode,
        uint256 area
    )
        public
        view
        returns (uint256)
    {
        KantahFee memory fee = kantahFees[kantahCode];

        require(fee.exists, "Kantah not set");

        uint256 landCost =
            (fee.landPricePerM2 * area) / 1000;

        return landCost + fee.registrationFee;
    }

    function pay(
        string memory applicationId,
        string memory kantahCode,
        uint256 area
    )
        external
        payable
    {
        require(
            payments[applicationId].payer == address(0),
            "Already paid"
        );

        uint256 requiredAmount =
            calculateCost(kantahCode, area);

        require(
            msg.value == requiredAmount,
            "Incorrect payment"
        );

        payments[applicationId] = PaymentInfo({
            payer: msg.sender,
            kantahCode: kantahCode,
            area: area,
            amount: msg.value,
            timestamp: block.timestamp
        });

        emit PaymentReceived(
            applicationId,
            kantahCode,
            msg.sender,
            area,
            msg.value,
            block.timestamp
        );
    }

    function isPaid(
        string memory applicationId
    )
        external
        view
        returns (bool)
    {
        return payments[applicationId].payer != address(0);
    }

    function getPaymentInfo(
        string memory applicationId
    )
        external
        view
        returns (PaymentInfo memory)
    {
        return payments[applicationId];
    }

    function withdraw()
        external
        onlyOwner
    {
        payable(owner).transfer(
            address(this).balance
        );
    }
}
